(() => {
  'use strict';
  const M=window.SWHomeModel,W=window.SWWorkspace,$=id=>document.getElementById(id),root=$('page-home');
  if(!root||!M||!W)return;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths={home:'<path d="m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 10h18M7 14h2m3 0h2m3 0h1M7 17h2m3 0h2"/>',bell:'<path d="M4 17c3-3 2-4 2-8a6 6 0 0 1 12 0c0 4-1 5 2 8ZM10 21h4M12 1v2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',moon:'<path d="M20 16A9 9 0 0 1 8 4a9 9 0 1 0 12 12Z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M3 21v-3a9 9 0 0 1 18 0v3Z"/>',note:'<path d="M5 3h10l4 4v14H5ZM14 3v6h5M8 12h8M8 16h6"/>',stack:'<path d="m12 3 10 6-10 6L2 9Zm-10 11 10 6 10-6M2 19l10 6 10-6"/>',check:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 11 4 4 7-8"/>',folder:'<path d="M3 20V5h7l3 3h8v3M3 20l3-9h16l-3 9Z"/>',chart:'<rect x="3" y="13" width="4" height="8" rx="1"/><rect x="10" y="8" width="4" height="13" rx="1"/><rect x="17" y="3" width="4" height="18" rx="1"/>',coins:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 4 18 4 18 0V5M3 10c0 4 18 4 18 0M3 15c0 4 18 4 18 0"/>',pie:'<path d="M12 3v9h9A9 9 0 1 1 9 3M15 2v7h7a9 9 0 0 0-7-7Z"/>',clock:'<path d="M3 12a9 9 0 1 1 3 7M3 6v6h6M12 7v6l4 2"/>'};
  const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[k]||paths.note}</svg>`;
  document.querySelectorAll('[data-hicon]').forEach(el=>el.innerHTML=icon(el.dataset.hicon));
  let period=M.monthRange(M.today().slice(0,7)),month=period.start.slice(0,7),taskDay=M.today(),theme='dark',anchor='',bookRaw=null,books=[],latest=[],notes=[],stats=null,invoiceSnapshot=null,salesData=null,salesError='',noteError='';
  const bookKey='sw_home_notebooks_v1',prefsKey='sw_home_preferences_v1';
  function status(message,error=false){$('homeStatus').textContent=message;$('homeStatus').hidden=!message;$('homeStatus').dataset.error=String(error);}
  try{const prefs=M.read(W.storage,prefsKey,x=>x&&typeof x==='object',{});if(prefs.start&&prefs.end)period=M.range(prefs.start,prefs.end);month=period.start.slice(0,7);theme=prefs.theme==='light'?'light':'dark';}catch{status('Dönem tercihi okunamadı. Geçerli ay gösteriliyor.',true);}
  function persistPrefs(){try{W.storage.setItem(prefsKey,JSON.stringify({...period,theme}));}catch{status('Görünüm tercihi kaydedilemedi.',true);}}
  function setTheme(){document.body.dataset.homeTheme=theme;$('homeTheme').innerHTML=icon(theme==='dark'?'sun':'moon');$('homeTheme').setAttribute('aria-label',theme==='dark'?'Açık temaya geç':'Koyu temaya geç');}
  function money(v){return v===null?'Hesaplanamadı':v.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2});}
  function monthLabel(v){return new Date(v+'-15T12:00:00Z').toLocaleDateString('tr-TR',{month:'long',year:'numeric',timeZone:'Europe/Istanbul'});}
  function dateLabel(v){return new Date(v+'T12:00:00Z').toLocaleDateString('tr-TR',{day:'numeric',month:'short',year:'numeric'});}
  function isFull(){const p=M.monthRange(month);return p.start===period.start&&p.end===period.end;}
  function open(title,html){$('homeDialogTitle').textContent=title;$('homeDialogBody').innerHTML=html;if(!$('homeDialog').open)$('homeDialog').showModal();}
  function close(){$('homeDialog').close();}
  $('homeDialogClose').onclick=close;
  function loadBooks(){bookRaw=W.storage.getItem(bookKey);books=bookRaw?JSON.parse(bookRaw):[];if(!Array.isArray(books)||books.some(b=>!b||typeof b.id!=='string'||typeof b.name!=='string'))throw Error('Not defterleri okunamadı. Mevcut kayıtların üzerine yazılmadı.');}
  function saveBooks(next){if(W.storage.getItem(bookKey)!==bookRaw)throw Error('Defterler başka sekmede değişti. Pencereyi kapatıp yeniden açın.');const raw=JSON.stringify(next);W.storage.setItem(bookKey,raw);bookRaw=raw;books=next;}
  function readNotes(){noteError='';try{notes=window.SWHomeNotes.list();loadBooks();}catch(e){noteError=e.message;notes=[];books=[];}}
  function taskDate(n){return M.day(n.taskDay)||M.day(n.due)||(n.created?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul'}).format(new Date(n.created)):'');}
  function noteRows(list,empty,limit=4){return list.slice(0,limit).map(n=>`<div class="home-note-row ${n.done?'is-done':''}"><input type="checkbox" data-note-toggle="${esc(n.id)}" aria-label="${esc(n.title)} tamamlandı" ${n.done?'checked':''}><button data-note-edit="${esc(n.id)}" title="${esc(n.body||n.title)}">${esc(n.title)}</button></div>`).join('')||`<p class="home-empty">${esc(empty)}</p>`;}
  function refreshNotes(){
    readNotes();const tasks=notes.filter(n=>n.column==='today'&&taskDate(n)===taskDay),done=tasks.filter(n=>n.done).length,pinned=notes.filter(n=>n.column==='permanent');
    $('homePinned').innerHTML=noteError?`<p class="home-empty">${esc(noteError)}</p>`:noteRows(pinned,'İlk notunu buraya iğnele.',5)+(pinned.length>5?'<button class="home-textlink" data-note-list="permanent">Tüm sabit notlar →</button>':'');
    $('homeTasks').innerHTML=noteRows(tasks,noteError||'Bu gün için görev yok.',4)+(tasks.length>4?'<button class="home-textlink" data-note-list="today">Tüm görevler →</button>':'');
    $('homeTaskCount').textContent=done+' / '+tasks.length;$('homeProgress').value=tasks.length?done/tasks.length*100:0;$('homeTaskDay').value=taskDay;
    const folders=[...books.map(b=>({...b,count:notes.filter(n=>n.notebookId===b.id).length})),...(notes.some(n=>!n.notebookId||!books.some(b=>b.id===n.notebookId))?[{id:'unfiled',name:'Diğer Notlar',count:notes.filter(n=>!n.notebookId||!books.some(b=>b.id===n.notebookId)).length}]:[])];
    $('homeBooks').innerHTML=folders.map((b,i)=>`<button class="home-folder tone-${i%4}" data-book="${esc(b.id)}">${icon('folder')}<span>${esc(b.name)}</span><b>${b.count}</b></button>`).join('')||'<p class="home-empty">Notlarını düzenlemek için bir defter oluştur.</p>';
    const reminders=notes.filter(n=>n.remind&&n.due&&!n.done).sort((a,b)=>a.due.localeCompare(b.due));
    $('homeReminders').innerHTML=reminders.slice(0,3).map((n,i)=>`<button data-note-edit="${esc(n.id)}" class="home-reminder tone-${i%3} ${new Date(n.due)<new Date()?'overdue':''}"><time>${esc(new Date(n.due).toLocaleDateString('tr-TR',{day:'numeric',month:'short'}))}</time><span>${esc(n.title)}${new Date(n.due)<new Date()?'<small>Gecikti</small>':''}</span></button>`).join('')||`<p class="home-empty">${esc(noteError||'Yaklaşan hatırlatıcın yok.')}</p>`;
    $('homeBadge').hidden=!reminders.length;$('homeBadge').textContent=reminders.length;$('homeNotifications').setAttribute('aria-label',reminders.length+' hatırlatıcıyı aç');
    const pct=tasks.length?Math.round(done/tasks.length*100):null;
    $('homeRing').style.setProperty('--done',(pct||0)+'%');$('homePercent').textContent=pct===null?'—':'%'+pct;
    $('homeLegend').innerHTML=`<p><i class="dot green"></i>Tamamlanan <b>${done}</b></p><p><i class="dot blue"></i>Devam eden <b>—</b></p><p><i class="dot amber"></i>Bekleyen <b>${tasks.length-done}</b></p><small>${tasks.length?'Görevlerde “devam eden” durumu tutulmuyor.':'Henüz görev yok.'}</small>`;
    renderCalendar();
  }
  function refreshData(){
    salesError='';try{invoiceSnapshot=window.SWInvoiceBridge.snapshot();}catch{invoiceSnapshot={rows:[],rawError:'Fatura listesi okunamadı.'};}
    stats=M.invoices(invoiceSnapshot.rows,period);
    const prior=M.invoices(invoiceSnapshot.rows,M.previous(period)),available=invoiceSnapshot.rows.length>0&&!invoiceSnapshot.rawError&&!invoiceSnapshot.loading;
    const labels=[['new','Yeni Gelen','note','green'],['processed','İşlenmiş','stack','blue'],['returned','İade','calendar','pink'],['foreign','Döviz','coins','purple']];
    $('homeMetrics').innerHTML=labels.map(([key,label,symbol,color])=>{const delta=available?M.change(stats[key],prior[key]):null;return `<button class="home-metric ${color}" data-invoices="${key}"><span class="home-metric-icon">${icon(symbol)}</span><span><span class="home-metric-label">${label}</span><strong>${available?stats[key].toLocaleString('tr-TR'):'—'}</strong><small>${delta===null?(available?'Önceki dönem: '+prior[key]:'Liste yüklenmedi'):`<span class="${delta<0?'negative':'positive'}">${delta<0?'▼':'▲'} %${Math.abs(delta)}</span> · Önceki: ${prior[key]}`}</small></span></button>`;}).join('');
    const key=W.companyId==='PUSULA'?'fc_sales_history_v1':W.companyId==='KIB'?'fc_sales_history_kib_v1':'fc_sales_history_'+W.companyId.toLowerCase()+'_v1';
    try{salesData=M.sales(M.read(W.storage,key,Array.isArray,[]),W.companyId,period);}catch{salesData={rows:[],total:null};salesError='Satış geçmişi okunamadı.';}
    const rows=[['efatura','Gelen E-Fatura',available?stats.rows.length:'—','note'],['satis','Satış Faturaları',salesError?'—':salesData.rows.length,'note'],['yevmiye','Yurt Dışı Yevmiye','—','folder'],['mutabakat','Cari Mutabakat','—','check']];
    if(document.querySelector('aside a[href$="/masraf/"]'))rows.splice(2,0,['masraf','Masraf Fişleri','—','note']);
    $('homeSummary').innerHTML=rows.map(([page,label,count,symbol],i)=>`<button class="home-summary-row tone-${i%4}" data-module="${page}">${icon(symbol)}<span>${label}</span><b>${count}</b></button>`).join('');
    $('homeFinance').innerHTML=[['Satışlar (aktarılan)',salesData.total],['Alımlar',null],['Giderler',null],['KDV (Hesaplanan)',null],['KDV (İndirilecek)',null]].map(([label,value])=>`<div class="home-finance-row"><span>${label}</span><strong class="${value===null?'unavailable':''}">${money(value)}</strong></div>`).join('')+'<p class="home-finance-note">'+esc(salesError||'Kâr veya vergi borcu hesaplanmaz.')+'</p>';
    latest=salesData.rows.map(r=>({date:M.day(r.tarih),number:r.docNo||'Satış faturası',status:'Logo’ya aktarıldı',module:'satis'})).sort((a,b)=>b.date.localeCompare(a.date));
    $('homeRecent').innerHTML=latest.slice(0,4).map(r=>`<button class="home-recent-row" data-module="satis">${icon('note')}<time>${dateLabel(r.date)}</time><strong>${esc(r.number)}</strong><span>${r.status}</span></button>`).join('')||`<p class="home-empty">${esc(salesError||'Bu dönemde kaydedilmiş satış aktarımı yok.')}</p>`;
    $('homeSourceCaption').textContent=invoiceSnapshot.rawError?'Gelen fatura verisi alınamadı: '+invoiceSnapshot.rawError:invoiceSnapshot.loading?'Fatura listesi yükleniyor…':'Kartlar: Gelen E-Fatura Takip açık listesi · Dönem: belge tarihi · İzibiz ayrıca toplanmaz · — : veri mevcut değil';
  }
  function renderCalendar(){
    $('homeCalendarLabel').textContent=monthLabel(month);const [y,m]=month.split('-').map(Number),offset=(new Date(y,m-1,1).getDay()+6)%7,count=new Date(y,m,0).getDate();
    $('homeCalendar').innerHTML='<span></span>'.repeat(offset)+Array.from({length:count},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0'),rem=notes.some(n=>n.remind&&!n.done&&M.day(n.due)===d),task=notes.some(n=>n.column==='today'&&taskDate(n)===d);return `<button data-home-day="${d}" class="${d===taskDay?'selected ':''}${!isFull()&&M.within(d,period)?'in-range ':''}${d===M.today()?'is-today':''}" aria-label="${dateLabel(d)}${rem?', hatırlatıcı var':''}${task?', görev var':''}" aria-pressed="${d===taskDay}">${i+1}<span>${rem?'<i class="dot purple"></i>':''}${task?'<i class="dot green"></i>':''}</span></button>`;}).join('');
  }
  function renderPeriod(){ $('homePeriodLabel').textContent=monthLabel(month);$('homeFilterSummary').textContent=W.companyName+' | '+(isFull()?monthLabel(month):dateLabel(period.start)+' – '+dateLabel(period.end));$('homeRangeClear').hidden=isFull();refreshData();renderCalendar();persistPrefs(); }
  function periodDialog(){open('Dönem seç',`<form id="homePeriodForm"><label>Ay ve yıl<input type="month" id="homeMonthInput" value="${month}" required></label><button type="button" id="homeMonthApply">Ayın tamamını seç</button><hr><p>Özel tarih aralığı (başlangıç ve bitiş dahil)</p><div class="home-form-pair"><label>Başlangıç<input type="date" id="homeStart" value="${period.start}" required></label><label>Bitiş<input type="date" id="homeEnd" value="${period.end}" required></label></div><p id="homeFormError" role="alert"></p><footer><button type="submit">Aralığı uygula</button></footer></form>`);$('homeMonthApply').onclick=()=>{try{month=$('homeMonthInput').value;period=M.monthRange(month);anchor='';renderPeriod();close();}catch(e){$('homeFormError').textContent=e.message;}};$('homePeriodForm').onsubmit=e=>{e.preventDefault();try{period=M.range($('homeStart').value,$('homeEnd').value);month=period.start.slice(0,7);anchor='';renderPeriod();close();}catch(error){$('homeFormError').textContent=error.message;}};}
  function editNote(id='',kind='permanent',book=''){
    readNotes();if(noteError){status(noteError,true);return;}
    const n=notes.find(n=>n.id===id);if(id&&!n){status('Bu not artık mevcut değil.',true);return;}
    const column=n?.column||(kind==='reminder'?'week':kind),due=n?.due||(kind==='reminder'?taskDay+'T09:00':''),folder=n?.notebookId||book;
    open(n?'Notu düzenle':kind==='today'?'Görev ekle':kind==='reminder'?'Hatırlatıcı ekle':'Yeni not',`<form id="homeNoteForm"><label>Başlık<input id="homeNoteTitle" maxlength="160" required value="${esc(n?.title||'')}"></label><label>Not<textarea id="homeNoteBody" maxlength="12000" rows="4">${esc(n?.body||'')}</textarea></label><div class="home-form-pair"><label>Gösterim<select id="homeNoteColumn">${[['permanent','Sabit Notlar'],['today','Günlük Yapılacaklar'],['week','Bu Hafta'],['ideas','Fikirler']].map(([v,t])=>`<option value="${v}" ${column===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Not defteri<select id="homeNoteBook"><option value="">Diğer Notlar</option>${books.map(b=>`<option value="${esc(b.id)}" ${folder===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label></div><div class="home-form-pair"><label>Görev günü<input type="date" id="homeNoteDay" value="${n?taskDate(n):taskDay}"></label><label>Hatırlatıcı (isteğe bağlı)<input type="datetime-local" id="homeNoteDue" value="${esc(due)}"></label></div><label class="home-checkbox"><input type="checkbox" id="homeNoteDone" ${n?.done?'checked':''}> Tamamlandı / üstünü çiz</label>${n?.table||n?.strokes?.length?'<p>Bu notun mevcut tablo ve çizimleri korunur. Gelişmiş düzenleyicide açabilirsiniz.</p><button type="button" id="homeAdvanced">Gelişmiş not düzenleyici</button>':''}<p id="homeFormError" role="alert"></p><footer>${n?'<button type="button" id="homeNoteDelete" class="home-danger">Notu sil</button>':''}<button type="submit">Kaydet</button></footer></form>`);
    if($('homeAdvanced'))$('homeAdvanced').onclick=()=>{close();window.SWHomeNotes.edit(id);};
    $('homeNoteForm').onsubmit=e=>{e.preventDefault();try{const title=$('homeNoteTitle').value.trim();if(!title)throw Error('Başlık yazın.');const day=$('homeNoteDay').value;if($('homeNoteColumn').value==='today'&&!M.day(day))throw Error('Görev günü seçin.');window.SWHomeNotes.put({...n,id:n?.id||crypto.randomUUID(),title,body:$('homeNoteBody').value,column:$('homeNoteColumn').value,notebookId:$('homeNoteBook').value,taskDay:day,due:$('homeNoteDue').value,remind:!!$('homeNoteDue').value,done:$('homeNoteDone').checked});close();refreshNotes();status('Kaydedildi.');}catch(error){$('homeFormError').textContent=error.message;}};
    if(n)$('homeNoteDelete').onclick=()=>deleteNote(n);
  }
  function deleteNote(n){open('Not silinsin mi?',`<p>“${esc(n.title)}” kaldırılacak. Son sağlam not yedeği korunur.</p><footer><button id="homeDeleteCancel">Vazgeç</button><button id="homeDeleteConfirm" class="home-danger">Notu sil</button></footer>`);$('homeDeleteCancel').onclick=()=>editNote(n.id);$('homeDeleteConfirm').onclick=()=>{try{window.SWHomeNotes.remove(n.id);close();refreshNotes();status('Not silindi.');}catch(e){status(e.message,true);}};}
  function notebook(id){readNotes();const b=books.find(x=>x.id===id),list=id==='unfiled'?notes.filter(n=>!n.notebookId||!books.some(b=>b.id===n.notebookId)):notes.filter(n=>n.notebookId===id);open(b?.name||'Diğer Notlar',`<div class="home-dialog-list">${noteRows(list,'Bu defterde henüz not yok.',10000)}</div><footer><button data-home-add="permanent" data-add-book="${b?esc(id):''}">＋ Not ekle</button>${b?'<button id="homeBookRename">Adını değiştir</button><button id="homeBookDelete">Defteri kaldır</button>':''}</footer>`);if(b){$('homeBookRename').onclick=()=>bookForm(b);$('homeBookDelete').onclick=()=>{open('Defter kaldırılsın mı?',`<p>Notlar silinmez; Diğer Notlar altında kalır.</p><button id="homeBookDeleteConfirm">Defteri kaldır</button>`);$('homeBookDeleteConfirm').onclick=()=>{try{saveBooks(books.filter(x=>x.id!==id));close();refreshNotes();}catch(e){status(e.message,true);}};};}}
  function bookForm(b){if(noteError){status(noteError,true);return;}open(b?'Defter adını değiştir':'Not defteri oluştur',`<form id="homeBookForm"><label>Defter adı<input id="homeBookName" maxlength="80" required value="${esc(b?.name||'')}"></label><p id="homeFormError" role="alert"></p><footer><button type="submit">Kaydet</button></footer></form>`);$('homeBookForm').onsubmit=e=>{e.preventDefault();try{const name=$('homeBookName').value.trim();if(!name)throw Error('Defter adı yazın.');saveBooks(b?books.map(x=>x.id===b.id?{...x,name}:x):[...books,{id:crypto.randomUUID(),name}]);close();refreshNotes();}catch(error){$('homeFormError').textContent=error.message;}};}
  function invoiceList(kind){const matches=stats.rows.filter(r=>kind==='all'||kind==='new'&&!r.islendi&&!r.isRet||kind==='processed'&&r.islendi&&!r.isRet||kind==='returned'&&r.isRet||kind==='foreign'&&r.birim&&!['TRY','TL','₺'].includes(String(r.birim).toUpperCase()));open('Dönemdeki faturalar',`<p>${esc($('homeFilterSummary').textContent)} · Gelen E-Fatura Takip</p>${invoiceSnapshot.rawError?'<p>Veri okunamadı.</p>':!invoiceSnapshot.rows.length?'<p>Önce Gelen E-Fatura Takip modülünde bir liste yükleyin.</p>':`<div class="home-records">${matches.map(r=>`<div><time>${esc(r.tarih)}</time><strong>${esc(r.fatno)}</strong><span>${r.isRet?'İade':r.islendi?'İşlenmiş':'Yeni'}</span></div>`).join('')||'<p>Bu aralıkta eşleşen fatura yok.</p>'}</div>`}<footer><button data-module="efatura">E-Fatura Takip’i aç →</button></footer>`);}
  function navigate(page){close();if(page==='masraf'){document.querySelector('aside a[href$="/masraf/"]')?.click();return;}showPage(page);}
  function allNotes(kind=''){readNotes();const list=notes.filter(n=>!kind||(kind==='today'?n.column==='today'&&taskDate(n)===taskDay:n.column===kind));open('Notlar',`<div class="home-dialog-list">${noteRows(list,noteError||'Henüz not yok.',10000)}</div><footer><button data-home-add="permanent">＋ Not ekle</button><button id="homeNotesExport">Not yedeği indir</button><button id="homeNotesRestore">Yedekten ekle</button></footer>`);$('homeNotesExport').onclick=()=>$('ntBackup').click();$('homeNotesRestore').onclick=()=>$('ntRestore').click();}
  function notifications(){readNotes();open('Hatırlatıcılar',`<p>Hatırlatmalar uygulama açıkken çalışır.</p><div class="home-dialog-list">${noteRows(notes.filter(n=>n.remind&&n.due).sort((a,b)=>a.due.localeCompare(b.due)),noteError||'Hatırlatıcı yok.',10000)}</div><footer><button data-home-add="reminder">＋ Hatırlatıcı ekle</button></footer>`);}
  function search(){refreshNotes();refreshData();const query=$('homeSearch').value.trim().toLocaleLowerCase('tr-TR');if(!query)return;const found=notes.filter(n=>(n.title+' '+n.body).toLocaleLowerCase('tr-TR').includes(query)),bills=stats.rows.filter(r=>(r.fatno+' '+r.unvan).toLocaleLowerCase('tr-TR').includes(query)),sale=salesData.rows.filter(r=>String(r.docNo||'').toLocaleLowerCase('tr-TR').includes(query));open('Arama sonuçları',`<p>${esc(W.companyName)} · Notlar ve seçilen dönemdeki kayıtlar</p><h3>Notlar</h3>${noteRows(found,'Eşleşen not yok.',10000)}<h3>Faturalar</h3>${bills.map(r=>`<button class="home-search-result" data-module="efatura">${esc(r.fatno)} · ${esc(r.unvan)}</button>`).join('')+sale.map(r=>`<button class="home-search-result" data-module="satis">${esc(r.docNo)}</button>`).join('')||'<p>Eşleşen fatura yok.</p>'}`);}
  document.addEventListener('click',e=>{
    const b=e.target.closest('button');if(!b||!b.closest('#page-home,#homeDialog'))return;
    if(b.dataset.homeMonth){const d=new Date(month+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.homeMonth));month=d.toISOString().slice(0,7);period=M.monthRange(month);anchor='';renderPeriod();}
    if(b.dataset.homeDay){taskDay=b.dataset.homeDay;if($('homeCalendarRange').checked){if(!anchor){anchor=taskDay;period={start:taskDay,end:taskDay};status('Şimdi aralığın bitiş gününü seçin.');}else{period={start:anchor<taskDay?anchor:taskDay,end:anchor>taskDay?anchor:taskDay};anchor='';status('Tarih aralığı uygulandı.');}renderPeriod();}refreshNotes();}
    if(b.dataset.homeAdd)editNote('',b.dataset.homeAdd,b.dataset.addBook||'');
    if(b.dataset.noteEdit)editNote(b.dataset.noteEdit);
    if(b.dataset.noteList)allNotes(b.dataset.noteList);
    if(b.dataset.book)notebook(b.dataset.book);
    if(b.dataset.invoices)invoiceList(b.dataset.invoices);
    if(b.dataset.module)navigate(b.dataset.module);
  });
  document.addEventListener('change',e=>{const id=e.target.dataset.noteToggle;if(!id)return;try{window.SWHomeNotes.toggle(id,e.target.checked);refreshNotes();}catch(error){e.target.checked=!e.target.checked;status(error.message,true);}});
  $('homeTaskDay').onchange=()=>{if(M.day($('homeTaskDay').value)){taskDay=$('homeTaskDay').value;refreshNotes();}};
  $('homeCalendarRange').onchange=()=>{anchor='';};
  $('homeTheme').onclick=()=>{theme=theme==='dark'?'light':'dark';setTheme();persistPrefs();};
  $('homePeriodOpen').onclick=$('homeCalendarLabel').onclick=periodDialog;
  $('homeRangeClear').onclick=()=>{period=M.monthRange(month);anchor='';renderPeriod();};
  $('homeAllNotes').onclick=()=>allNotes();$('homeBookAdd').onclick=()=>{readNotes();bookForm();};$('homeNotifications').onclick=notifications;
  $('homeRecentAll').onclick=()=>open('Kaydedilmiş satış aktarımları',`<div class="home-records">${latest.map(r=>`<button data-module="satis">${dateLabel(r.date)} · ${esc(r.number)} · ${r.status}</button>`).join('')||'<p>Bu dönemde kayıt yok.</p>'}</div>`);
  $('homeProfile').onclick=()=>{if(window.SW_CONTEXT)location.href='/account';else open('Yerel çalışma alanı',`<p>${esc(W.companyName)} firmasının bu cihazdaki kayıtları açık.</p><p>Hesap yönetimi çevrimiçi uygulamada kullanılabilir.</p>`);};
  $('homeSearchForm').onsubmit=e=>{e.preventDefault();search();};
  $('homeSources').onclick=()=>open('Veri kaynakları',`<p><b>Üst kartlar:</b> Gelen E-Fatura Takip’te açık olan liste. Tarih filtresi fatura tarihine uygulanır; yüklenmiş dosyada bulunmayan dönemler kıyaslanamaz. Yeni, işlenmiş ve iade mevcut satır durumudur; işlemin yapıldığı tarih sistemde tutulmuyor.</p><p><b>İzibiz:</b> Ayrı bir toplam eklenmez; mükerrer sayım yapılmaz.</p><p><b>Satışlar ve son işlemler:</b> Aktif firmanın Logo’ya aktarıldı olarak kaydedilmiş satış geçmişi. Tutarlar mevcut satış modülünün TL toplamlarıdır.</p><p><b>Masraf, yurt dışı, mutabakat ve KDV:</b> Bu ana sayfaya bağlı doğrulanmış dönemsel veri kaynağı yok; — / hesaplanamadı gösterilir.</p><p><b>Performans:</b> Yalnızca seçilen günün görevleri. Görevlerde devam ediyor bilgisi tutulmaz.</p><p><b>Notlar:</b> Mevcut firma not deposu; eski notların içerikleri, tabloları, çizimleri ve yedekleri korunur.</p>`);
  function clock(){const now=new Date();$('homeToday').textContent=now.toLocaleDateString('tr-TR',{timeZone:'Europe/Istanbul',day:'numeric',month:'long',year:'numeric',weekday:'long'});$('homeTime').textContent=now.toLocaleTimeString('tr-TR',{timeZone:'Europe/Istanbul',hour12:false});}
  const refresh=()=>{if(document.body.classList.contains('fc-home-full')){refreshNotes();renderPeriod();}};
  document.addEventListener('sw:notes-changed',()=>{refreshNotes();});
  window.addEventListener('storage',e=>{if(e.key?.startsWith('sw:company:v2:'+W.companyId+':'))refresh();});
  new MutationObserver(refresh).observe(root,{attributes:true,attributeFilter:['style']});
  setTheme();clock();setInterval(clock,1000);refreshNotes();renderPeriod();
})();
